\section*{Claim}
The paper's claimed boundary-implementation robustness is valid for the electric-center and trivial-center subfamily whenever gauge fixing the boundary maximal tree changes the source and vacuum path integrals only by source-independent positive constants. Under that condition,
\[
\widetilde S^{(q)}_{A_E|Q\bar Q}=\widetilde S^{(q)}_{A_0|Q\bar Q}.
\]
This is a scoped statement about the two implemented boundary prescriptions, not a proof for uncomputed magnetic-center constructions.

\section*{Premises}
\[
\begin{array}{ll}
\text{(P1)} & A\in\{A_E,A_0\},\text{ where }A_E\text{ is electric-center and }A_0\text{ is trivial-center}.\\[1mm]
\text{(P2)} & \displaystyle R_q(A):=\frac{Z_A^{(q)}(Q\bar Q)/Z_A(Q\bar Q)^q}{Z_A^{(q)}/Z_A^q},
\qquad R_q(A)>0.\\[5mm]
\text{(P3)} & \displaystyle \widetilde S^{(q)}_{A|Q\bar Q}:=-\frac{1}{q-1}\log R_q(A).\\[3mm]
\text{(P4)} & \displaystyle Z_{A_0}^{(q)}=c_qZ_{A_E}^{(q)},
\qquad Z_{A_0}=c_1Z_{A_E}.\\[2mm]
\text{(P5)} & \displaystyle Z_{A_0}^{(q)}(Q\bar Q)=c_qZ_{A_E}^{(q)}(Q\bar Q),
\qquad Z_{A_0}(Q\bar Q)=c_1Z_{A_E}(Q\bar Q).\\[2mm]
\text{(P6)} & c_q>0,
\quad c_1>0,
\quad c_q,c_1\text{ do not depend on the Polyakov-loop sources}.\\[1mm]
\end{array}
\]

\section*{Derivation}
Substitute (P4) and (P5) into the trivial-center ratio:
\begin{align}
R_q(A_0)
&=\frac{Z_{A_0}^{(q)}(Q\bar Q)/Z_{A_0}(Q\bar Q)^q}{Z_{A_0}^{(q)}/Z_{A_0}^q} && \text{by (P2)}\\
&=\frac{c_qZ_{A_E}^{(q)}(Q\bar Q)/(c_1Z_{A_E}(Q\bar Q))^q}{c_qZ_{A_E}^{(q)}/(c_1Z_{A_E})^q} && \text{by (P4),(P5)}\\
&=\frac{c_qc_1^{-q}Z_{A_E}^{(q)}(Q\bar Q)/Z_{A_E}(Q\bar Q)^q}{c_qc_1^{-q}Z_{A_E}^{(q)}/Z_{A_E}^q} && \text{factor constants}\\
&=\frac{Z_{A_E}^{(q)}(Q\bar Q)/Z_{A_E}(Q\bar Q)^q}{Z_{A_E}^{(q)}/Z_{A_E}^q} && \text{cancel the same positive factor}\\
&=R_q(A_E). && \text{by (P2)}
\end{align}
The entropies are therefore equal:
\begin{align}
\widetilde S^{(q)}_{A_0|Q\bar Q}
&=-\frac{1}{q-1}\log R_q(A_0) && \text{by (P3)}\\
&=-\frac{1}{q-1}\log R_q(A_E) && \text{ratio equality}\\
&=\widetilde S^{(q)}_{A_E|Q\bar Q}. && \text{by (P3)}
\end{align}

\section*{Final Result}
\[
\boxed{\displaystyle R_q(A_0)=R_q(A_E)
\quad\Longrightarrow\quad
\widetilde S^{(q)}_{A_0|Q\bar Q}=\widetilde S^{(q)}_{A_E|Q\bar Q}}
\]
\hfill$\blacksquare$

deeper_reasoning_5:
\section*{Claim}
For the fully cross-cut \(SU(2)\) half-slab geometry, the internal color model provides a sharp baseline. If the continuum-extrapolated second Renyi flux-tube entropy is
\[
S_0:=\lim_{a\to0}\widetilde S^{(2)}_{|Q\bar Q}(a,L,w,x,y)
\]
in the complete-cross-cut regime, then under the additive interpretation
\[
S_0=2\log2+S_{\rm vibrational}.
\]
Consequently, \(S_0>2\log2\) is exactly the condition for a positive resolved vibrational contribution in this model.

\section*{Premises}
\[
\begin{array}{ll}
\text{(P1)} & \displaystyle \widetilde S^{(2)}_{|Q\bar Q}=S_{\rm internal}+S_{\rm vibrational}.\\[2mm]
\text{(P2)} & \displaystyle S_{\rm internal}=\langle F\rangle\log N_c.\\[2mm]
\text{(P3)} & \displaystyle N_c=2.\\[1mm]
\text{(P4)} & \displaystyle \langle F\rangle=2\text{ in the fully cross-cut fundamental flux-tube regime}.\\[1mm]
\text{(P5)} & \displaystyle S_0:=\lim_{a\to0}\widetilde S^{(2)}_{|Q\bar Q}(a,L,w,x,y)\text{ exists in that regime}.\\[1mm]
\end{array}
\]

\section*{Derivation}
The internal baseline is
\begin{align}
S_{\rm internal}
&=\langle F\rangle\log N_c && \text{by (P2)}\\
&=2\log2 && \text{by (P3),(P4)}.
\end{align}
Taking the continuum limit of the additive interpretation gives
\begin{align}
S_0
&=2\log2+S_{\rm vibrational} && \text{by (P1),(P5)}.
\end{align}
Solving for the vibrational term,
\begin{align}
S_{\rm vibrational}
&=S_0-2\log2.
\end{align}
Therefore
\begin{align}
S_{\rm vibrational}>0
&\Longleftrightarrow S_0-2\log2>0\\
&\Longleftrightarrow S_0>2\log2.
\end{align}
Likewise, if \(S_0\) is statistically indistinguishable from \(2\log2\), this model does not resolve a positive vibrational contribution; it does not prove that such a contribution is absent.

\section*{Final Result}
\[
\boxed{\displaystyle S_0=2\log2+S_{\rm vibrational},
\qquad
S_{\rm vibrational}>0\Longleftrightarrow S_0>2\log2}
\]
\hfill$\blacksquare$
